# AKAH BOT - R54-P0R1 targeted source authority audit; read-only.
# One command, self-contained. Never opens 2024 market data, never mutates repository.
$ErrorActionPreference = 'Stop'
$Repo = 'C:\SIRAJ\Repositories\spot-speculation-bot'
$Downloads = Join-Path $HOME 'Downloads'
if (-not (Test-Path -LiteralPath $Repo -PathType Container)) { Write-Host "R54_P0R1_ERROR=REPO_NOT_FOUND"; exit 2 }
if (-not (Test-Path -LiteralPath $Downloads -PathType Container)) { Write-Host "R54_P0R1_ERROR=DOWNLOADS_NOT_FOUND"; exit 3 }
$Stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$Work = Join-Path $Downloads ("AKAH_R54_P0R1_WORKER_" + $Stamp)
New-Item -ItemType Directory -Path $Work -Force | Out-Null
$Worker = Join-Path $Work 'r54_p0r1_worker.py'
$Encoded = @'

'@
[System.IO.File]::WriteAllBytes($Worker, [System.Convert]::FromBase64String($Encoded.Trim()))
$Python = Join-Path $Repo '.venv\Scripts\python.exe'
$ArgsPrefix = @()
if (-not (Test-Path -LiteralPath $Python -PathType Leaf)) {
    $cmd = Get-Command py -ErrorAction SilentlyContinue
    if ($null -ne $cmd) { $Python = $cmd.Source; $ArgsPrefix = @('-3') }
    else {
        $cmd = Get-Command python -ErrorAction SilentlyContinue
        if ($null -eq $cmd) { Write-Host 'R54_P0R1_ERROR=PYTHON_NOT_FOUND'; exit 4 }
        $Python = $cmd.Source
    }
}
$Log = Join-Path $Work 'R54_P0R1_RUN_FULL.log'
& $Python @ArgsPrefix $Worker --repo $Repo --downloads $Downloads 2>&1 | Tee-Object -FilePath $Log
$Code = $LASTEXITCODE
if ($null -eq $Code) { $Code = 1 }
Write-Host "R54_P0R1_EXIT_CODE=$Code"
exit $Code
